INSERT INTO material_grades (name,normalized_name,aliases,category,data_status,source_note,source_material_id,catalog_section,material_class,industrial_use,verification_status,source_url,source_retrieved_at,source_name,decoding_summary,decoding) VALUES ('20','20','["20"]'::jsonb,'steel','needs_review','Автоматический импорт; одна исходная запись','mat_a0b8651540c7c983','stk','Сталь конструкционная углеродистая качественная','20А: после нормализации или без термообработки крюки кранов, муфты, вкладыши подшипников и другие детали, работающие при температуре от -40 до 450 °С под давлением, после ХТО - шестерни, червяки и другие детали, к которым предъявляются требования высокой поверхностной твердости при невысокой прочности сердцевины; 20кп, 20пс: без термообработки или нормализации - патрубки, штуцера, вилки, болты, фланцы, корпуса аппаратов и другие детали из кипящей стали, работающие от -20 до 425 °С, после цементации и цианирования - детали от которых требуется высокая твердость поверхности и невысокая прочность сердцевины (оси, крепежные детали, пальцы, звездочки)','imported_unverified','https://metallicheckiy-portal.ru/marki_metallov/stk','2026-07-12T18:20:26.051662+00:00','Центральный металлический портал','Автоматическая расшифровка не определена; требуется проверка по нормативному документу.','{"grade":"20","tokens":[],"summary":"Автоматическая расшифровка не определена; требуется проверка по нормативному документу.","source":"Справка «Расшифровка марок сталей», ИСС «Техэксперт»","status":"reference_interpretation"}'::jsonb) ON CONFLICT (normalized_name) DO UPDATE SET aliases=EXCLUDED.aliases, source_note=EXCLUDED.source_note, source_material_id=EXCLUDED.source_material_id, catalog_section=EXCLUDED.catalog_section, material_class=EXCLUDED.material_class, industrial_use=EXCLUDED.industrial_use, verification_status=EXCLUDED.verification_status, source_url=EXCLUDED.source_url, source_retrieved_at=EXCLUDED.source_retrieved_at, source_name=EXCLUDED.source_name, de